//! BGV fixture data embedded in the WASM binary.
//!
//! The fixtures are generated by running:
//! ```
//! cargo run -p mpz-justvengers-core --example generate_bgv_fixture_binary
//! ```
//!
//! This module embeds the secret and public key (~1MB total) to skip
//! the expensive key generation step. Galois keys (~170MB) are NOT embedded
//! due to size constraints and are generated at runtime.

use mpz_justvengers_core::{RnsKeyPair, RnsPublicKey, RnsSecretKey, RnsGaloisKeys};
use std::sync::OnceLock;

/// Embedded secret key binary data.
static SECRET_KEY_BYTES: &[u8] = include_bytes!("../../../../bgv_fixtures/secret_key.bin");

/// Embedded public key binary data.
static PUBLIC_KEY_BYTES: &[u8] = include_bytes!("../../../../bgv_fixtures/public_key.bin");

/// Cached RNS keypair (loaded once from embedded bytes).
static CACHED_KEYPAIR: OnceLock<RnsKeyPair> = OnceLock::new();

/// Cached Galois keys (generated once at runtime).
static CACHED_GALOIS_KEYS: OnceLock<RnsGaloisKeys> = OnceLock::new();

/// Returns the preloaded RNS keypair.
///
/// The keypair is deserialized from embedded binary data on first access.
/// Subsequent calls return a clone of the cached keypair.
pub fn get_preloaded_rns_keypair() -> RnsKeyPair {
    CACHED_KEYPAIR.get_or_init(|| {
        #[cfg(target_arch = "wasm32")]
        web_sys::console::log_1(&"[fixtures] Deserializing embedded RNS keypair...".into());

        let sk: RnsSecretKey = bincode::deserialize(SECRET_KEY_BYTES)
            .expect("Failed to deserialize secret key from embedded bytes");
        let pk: RnsPublicKey = bincode::deserialize(PUBLIC_KEY_BYTES)
            .expect("Failed to deserialize public key from embedded bytes");

        #[cfg(target_arch = "wasm32")]
        web_sys::console::log_1(&"[fixtures] RNS keypair loaded from embedded data".into());

        RnsKeyPair { sk, pk }
    }).clone()
}

/// Returns or generates the Galois keys.
///
/// On first call, this generates the Galois keys from the preloaded secret key,
/// which takes approximately 30-60 seconds. Subsequent calls return a clone
/// of the cached keys.
///
/// The progress callback is called during generation to report status.
#[cfg(target_arch = "wasm32")]
pub fn get_or_generate_galois_keys() -> RnsGaloisKeys {
    use mpz_core::prg::Prg;

    CACHED_GALOIS_KEYS.get_or_init(|| {
        web_sys::console::log_1(&"[fixtures] Generating Galois keys (this takes ~30-60 seconds)...".into());

        let keypair = get_preloaded_rns_keypair();
        let mut rng = Prg::new_with_seed([0u8; 16]);

        let start = web_sys::window().unwrap().performance().unwrap().now();
        let galois_keys = RnsGaloisKeys::generate(&keypair.sk, &mut rng);
        let elapsed = web_sys::window().unwrap().performance().unwrap().now() - start;

        web_sys::console::log_1(&format!("[fixtures] Galois keys generated in {:.1}s", elapsed / 1000.0).into());

        galois_keys
    }).clone()
}

/// Returns or generates the Galois keys (non-WASM version).
#[cfg(not(target_arch = "wasm32"))]
pub fn get_or_generate_galois_keys() -> RnsGaloisKeys {
    use mpz_core::prg::Prg;

    CACHED_GALOIS_KEYS.get_or_init(|| {
        eprintln!("[fixtures] Generating Galois keys...");

        let keypair = get_preloaded_rns_keypair();
        let mut rng = Prg::new_with_seed([0u8; 16]);

        let galois_keys = RnsGaloisKeys::generate(&keypair.sk, &mut rng);

        eprintln!("[fixtures] Galois keys generated");

        galois_keys
    }).clone()
}
